  const QString initial="% Finite burn selection sentinel Ω\nCreate ChemicalTank ChemFuel;\nChemFuel.FuelMass = 23;\nCreate ElectricTank ElecFuel;\nElecFuel.FuelMass = 17;\nCreate ChemicalThruster ChemOne ChemTwo;\nChemOne.Tank = {ChemFuel};\nChemTwo.Tank = {ChemFuel};\nCreate ElectricThruster ElecOne ElecTwo;\nElecOne.Tank = {ElecFuel};\nElecTwo.Tank = {ElecFuel};\nCreate Spacecraft Sat;\nSat.DryMass = 910.25;\nCreate GroundStation Site;\nCreate ImpulsiveBurn Impulse;\nCreate FiniteBurn Burn;\nBurn.Thrusters = {"+first+"};\nCreate Variable Keep;\nKeep = 41;\nBeginMissionSequence;\nKeep = Keep + 1;\n% preserve finite burn tail Ω\n";
